class RoroFile extends RoroElement{filenameLabelTemplate;filenameLabelContainer;wrapper;constructor(id=null){super("file",id);const self=this;self.ready.then(function(){self.init(),self.registerEvents()})}init(){this.elt&&(this.wrapper=this.elt.closest(".roro-wrapper"),this.filenameLabelTemplate=RoroDom.qs(this.wrapper,".roro-file-name"),this.filenameLabelContainer=RoroDom.qs(this.wrapper,".roro-file-name-container"))}registerEvents(){if(!this.filenameLabelTemplate)return;const self=this;RoroDom.on(self.elt,"change",function(){self.filenameLabelContainer.replaceChildren(),Array.from(self.elt.files).forEach(function(file,index){const label=self.filenameLabelTemplate.cloneNode(!0);RoroDom.show(label);const text=RoroDom.qs(label,".roro-file-name-text");text&&(text.textContent=file.name);const del=RoroDom.qs(label,".roro-file-name-delete");RoroDom.on(del,"click",function(){const dt=new DataTransfer;Array.from(self.elt.files).forEach((f,i)=>{i!==index&&dt.items.add(f)}),self.elt.files=dt.files,label.remove()}),self.filenameLabelContainer.appendChild(label)})})}}window.RoroFile=RoroFile;
